sys_script_include.script:
var UpdateVariableQuestion = Class.create();
UpdateVariableQuestion.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
   updateQuestionText: function() {
      var sysId = this.getParameter('sysparm_sys_id');
      var variableName = this.getParameter('sysparm_variable_name');
      var newQuestionText = this.getParameter('sysparm_new_question_text');

      var rp = new GlideRecord('sc_cat_item_producer');
      if (rp.get('sys_id', sysId)) {
         var variable = new GlideRecord('item_option_new');
         variable.addQuery('cat_item', rp.sys_id);
         variable.addQuery('name', variableName);
         variable.query();

         if (variable.next()) {
            variable.question_text = newQuestionText;
            variable.update();
            return 'success';
         }
      }
      return 'failure';
   },
   type: 'UpdateVariableQuestion'
});
